!function(w,d){function Ad(c){this.c=c;this.q=[]}Ad.prototype.req=function(p,cb){var x=new XMLHttpRequest;x.open('POST','/api/ad_request.php');x.setRequestHeader('Content-Type','application/json');x.onload=function(){var r=JSON.parse(x.responseText);if(r.code===0&&r.data){cb&&cb(r.data);Ad.render(r.data)}};x.send(JSON.stringify({position_code:p}))};Ad.render=function(a){var e=d.querySelector('[data-pos="'+a.request_id+'"]');if(e)e.innerHTML='<a href="'+a.landing_url+'" target="_blank"><img src="'+a.image_url+'" width="100%"></a><img src="/api/ad_impression.php?id='+a.creative_id+'" style="display:none">'};d.querySelectorAll('[data-ad]').forEach(function(el){var sdk=new Ad();sdk.req(el.dataset.ad)});w.AdSDK=Ad}(window,document);
